CREATE   PROCEDURE [dbo].[sp_Booth_Create]
    @SpaceId    INT,
    @MapSpotId  INT,
    @ModifiedBy NVARCHAR(255),
    @CreatedBy  NVARCHAR(255),
    @I18nName   NVARCHAR(MAX) = NULL,
    @MediaItems NVARCHAR(MAX) = NULL,
    @IconKey    VARCHAR(50)   = NULL -- NEW
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- 1. Validate map_spot
        IF NOT EXISTS (SELECT 1 FROM map_spot WHERE id = @MapSpotId)
            THROW 50002, 'MapSpot not found.', 1;

        -- 2. Insert booth - name_key generated by table DEFAULT (NEWID())
        DECLARE @BoothId INT;
        DECLARE @NameKey UNIQUEIDENTIFIER;

        DECLARE @BoothOut TABLE (booth_id INT NOT NULL, name_key UNIQUEIDENTIFIER NOT NULL);

        INSERT INTO booth (space_id, map_spot_id, modified_by, created_by, icon_key)
        OUTPUT INSERTED.id, INSERTED.name_key INTO @BoothOut
        VALUES (@SpaceId, @MapSpotId, @ModifiedBy, @CreatedBy, @IconKey);

        SELECT @BoothId = booth_id, @NameKey = name_key FROM @BoothOut;

        -- 3. Name i18n - filtered to supported locales only
        IF @I18nName IS NOT NULL
        BEGIN
            INSERT INTO i18n ([key], locale_id, [value], space_id, modified_by, modified_time, created_by)
            SELECT @NameKey, j.locale_id, j.[value], @SpaceId, @ModifiedBy, SYSUTCDATETIME(), @CreatedBy
            FROM   OPENJSON(@I18nName) WITH (
                       locale_id NVARCHAR(20)  '$.locale_id',
                       [value]   NVARCHAR(MAX) '$.value'
                   ) j
            INNER JOIN supported_languages sl
                ON  sl.locale_id = j.locale_id
               AND (sl.space_id  = @SpaceId OR sl.space_id IS NULL);
        END;

        -- 4. Media items
        IF @MediaItems IS NOT NULL
        BEGIN
            CREATE TABLE #NewMedia (
                row_num         INT           NOT NULL IDENTITY(1,1) PRIMARY KEY,
                media_type_id   INT           NOT NULL,
                text_key        NVARCHAR(MAX) NULL,
                description_key NVARCHAR(MAX) NULL,
                link_locs       NVARCHAR(MAX) NULL,
                text_locs       NVARCHAR(MAX) NULL,
                desc_locs       NVARCHAR(MAX) NULL
            );

            INSERT INTO #NewMedia (media_type_id, text_key, description_key, link_locs, text_locs, desc_locs)
            SELECT
                CAST(JSON_VALUE(value, '$.media_type_id')  AS INT),
                     JSON_VALUE(value, '$.text_key'),
                     JSON_VALUE(value, '$.description_key'),
                     JSON_QUERY(value, '$.link_locs'),
                     JSON_QUERY(value, '$.text_locs'),
                     JSON_QUERY(value, '$.desc_locs')
            FROM OPENJSON(@MediaItems);

            DECLARE @MRow         INT = 1;
            DECLARE @MMaxRow      INT = (SELECT COUNT(1) FROM #NewMedia);
            DECLARE @MediaId      BIGINT;
            DECLARE @MMediaType   INT;
            DECLARE @MTextKey     NVARCHAR(MAX);
            DECLARE @MDescKey     NVARCHAR(MAX);
            DECLARE @MLinkLocs    NVARCHAR(MAX);
            DECLARE @MTextLocs    NVARCHAR(MAX);
            DECLARE @MDescLocs    NVARCHAR(MAX);
            DECLARE @MTextKeyGuid UNIQUEIDENTIFIER;
            DECLARE @MDescKeyGuid UNIQUEIDENTIFIER;

            WHILE @MRow <= @MMaxRow
            BEGIN
                SET @MTextKeyGuid = NULL;
                SET @MDescKeyGuid = NULL;

                SELECT
                    @MMediaType = media_type_id,
                    @MTextKey   = text_key,
                    @MDescKey   = description_key,
                    @MLinkLocs  = link_locs,
                    @MTextLocs  = text_locs,
                    @MDescLocs  = desc_locs
                FROM #NewMedia WHERE row_num = @MRow;

                -- Resolve keys - generate new GUID when locs exist but no key provided
                SET @MTextKeyGuid = TRY_CAST(@MTextKey AS UNIQUEIDENTIFIER);
                IF @MTextKeyGuid IS NULL AND @MTextLocs IS NOT NULL
                    SET @MTextKeyGuid = NEWID();

                SET @MDescKeyGuid = TRY_CAST(@MDescKey AS UNIQUEIDENTIFIER);
                IF @MDescKeyGuid IS NULL AND @MDescLocs IS NOT NULL
                    SET @MDescKeyGuid = NEWID();

                -- Insert media
                INSERT INTO media (space_id, media_type_id, text_key, description_key, modified_by, modified_time, created_by)
                VALUES (@SpaceId, @MMediaType, @MTextKeyGuid, @MDescKeyGuid, @ModifiedBy, SYSUTCDATETIME(), @CreatedBy);

                SET @MediaId = SCOPE_IDENTITY();

                -- link_locs - filtered to supported locales
                IF @MLinkLocs IS NOT NULL
                BEGIN
                    INSERT INTO media_localization (media_id, locale_id, media_link, modified_by, modified_time, created_by)
                    SELECT @MediaId, j.locale_id, j.media_link, @ModifiedBy, SYSUTCDATETIME(), @CreatedBy
                    FROM   OPENJSON(@MLinkLocs) WITH (
                               locale_id  NVARCHAR(20)  '$.locale_id',
                               media_link NVARCHAR(MAX) '$.media_link'
                           ) j
                    INNER JOIN supported_languages sl
                        ON  sl.locale_id = j.locale_id
                       AND (sl.space_id  = @SpaceId OR sl.space_id IS NULL);
                END;

                -- text_locs - filtered to supported locales
                IF @MTextLocs IS NOT NULL AND @MTextKeyGuid IS NOT NULL
                BEGIN
                    INSERT INTO i18n ([key], locale_id, [value], space_id, modified_by, modified_time, created_by)
                    SELECT @MTextKeyGuid, j.locale_id, j.[value], @SpaceId, @ModifiedBy, SYSUTCDATETIME(), @CreatedBy
                    FROM   OPENJSON(@MTextLocs) WITH (
                               locale_id NVARCHAR(20)  '$.locale_id',
                               [value]   NVARCHAR(MAX) '$.value'
                           ) j
                    INNER JOIN supported_languages sl
                        ON  sl.locale_id = j.locale_id
                       AND (sl.space_id  = @SpaceId OR sl.space_id IS NULL);
                END;

                -- desc_locs - filtered to supported locales
                IF @MDescLocs IS NOT NULL AND @MDescKeyGuid IS NOT NULL
                BEGIN
                    INSERT INTO i18n ([key], locale_id, [value], space_id, modified_by, modified_time, created_by)
                    SELECT @MDescKeyGuid, j.locale_id, j.[value], @SpaceId, @ModifiedBy, SYSUTCDATETIME(), @CreatedBy
                    FROM   OPENJSON(@MDescLocs) WITH (
                               locale_id NVARCHAR(20)  '$.locale_id',
                               [value]   NVARCHAR(MAX) '$.value'
                           ) j
                    INNER JOIN supported_languages sl
                        ON  sl.locale_id = j.locale_id
                       AND (sl.space_id  = @SpaceId OR sl.space_id IS NULL);
                END;

                -- booth_media link (idempotent upsert)
                DELETE FROM booth_media WHERE booth_id = @BoothId AND media_id = @MediaId;
                INSERT INTO booth_media (booth_id, media_id, modified_by, modified_time, created_by)
                VALUES (@BoothId, @MediaId, @ModifiedBy, SYSUTCDATETIME(), @CreatedBy);

                SET @MRow = @MRow + 1;
            END; -- WHILE

            DROP TABLE #NewMedia;
        END; -- IF @MediaItems IS NOT NULL

        COMMIT TRANSACTION;
        SELECT @BoothId AS booth_id, @NameKey AS name_key;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        IF OBJECT_ID('tempdb..#NewMedia') IS NOT NULL DROP TABLE #NewMedia;
        THROW;
    END CATCH
END;
